 function sign(text,pos,w,h,owner='equipment',ground=false){const c=document.createElement('canvas');c.width=512;c.height=128;const x=c.getContext('2d');x.fillStyle=ground?'#954a3c':'#294c43';x.fillRect(0,0,512,128);x.fillStyle='#eae8d7';x.font='600 62px Microsoft YaHei';x.textAlign='center';x.textBaseline='middle';x.fillText(text,256,65,490);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;ts.add(t);const m=M(new THREE.MeshStandardMaterial({map:t,roughness:.85}));m.name='sign '+text;const o=new THREE.Mesh(G(new THREE.PlaneGeometry(w,h)),m);o.position.fromArray(pos);if(ground)o.rotation.x=-Math.PI/2;groups.get(owner).add(o);return o;}
