 box('paving',0,-.2,0,112,.4,112);ring('Red rubber running track',23,27.4,.12,'rubber');ring('Outer safety margin',27.4,28,.115,'rubber-edge');for(let lane=0;lane<=4;lane++)ring('Continuous lane line '+lane,23+lane*1.1-.022,23+lane*1.1+.022,.141,'paint');
 const shape=new THREE.Shape();shape.moveTo(23,-26);shape.lineTo(23,26);shape.absarc(0,26,23,0,Math.PI,false);shape.lineTo(-23,-26);shape.absarc(0,-26,23,Math.PI,Math.PI*2,false);const infield=new THREE.Mesh(G(new THREE.ShapeGeometry(shape,80)),materials['grass-0']);infield.rotation.x=-Math.PI/2;infield.position.y=.09;infield.receiveShadow=true;groups.get('pitch').add(infield);for(let i=0;i<10;i++)box(i%2?'grass-0':'grass-1',0,.10,-30.6+i*6.8,42,.08,6.8,'pitch');
