 function person(id,material){const g=new THREE.Group();g.name=id;groups.get('life').add(g);mesh('sphere','skin',[0,1.65,0],[.32,.38,.32],g);mesh('box',material,[0,1.1,0],[.43,.65,.26],g);const limbs=[];for(const x of [-.13,.13]){const pivot=new THREE.Group();pivot.position.set(x,.8,0);g.add(pivot);mesh('box','dark',[0,-.35,0],[.15,.7,.17],pivot);limbs.push(pivot);}for(const x of [-.3,.3]){const a=new THREE.Group();a.position.set(x,1.35,0);g.add(a);mesh('box','skin',[0,-.24,0],[.12,.48,.14],a);limbs.push(a);}return{g,limbs};}
 for(let i=0;i<16;i++)people.push({...person('Runner '+i,'runner'),lane:i%4,offset:Math.floor(i/4)/4,kind:'runner',i});
 for(let i=0;i<8;i++)people.push({...person('Player '+i,i%2?'team-red':'team-blue'),kind:'player',i});
 const ball=mesh('sphere','ball',[0,.27,0],[.23,.23,.23],groups.get('life'));ball.name='Rolling football';for(let i=0;i<10;i++){const a=i*2.4,b=i*.9;const dot=mesh('sphere','dark',[Math.sin(a)*Math.cos(b)*.105,Math.sin(b)*.105,Math.cos(a)*Math.cos(b)*.105],[.045,.045,.045],ball);dot.scale.multiplyScalar(1/.23);dot.position.multiplyScalar(1/.23);}
 const ballPath=new THREE.CatmullRomCurve3([[0,20],[12,8],[-12,0],[0,-25],[0,-34],[0,-35.2],[10,-20],[0,20]].map(([x,z])=>new THREE.Vector3(x,.27,z)),true,'centripetal');
 let boardSlide=-1;
 function update(delta=0){if(disposed)return;const dt=enabled&&Number.isFinite(delta)?THREE.MathUtils.clamp(delta,0,.25):0;time+=dt;if(wind)windTime+=dt;windShaders.forEach(s=>s.uniforms.windTime.value=windTime);const bp=ballPath.getPointAt((time*.025)%1);ball.position.copy(bp);ball.rotation.x=time*7;ball.rotation.z=time*1.7;ball.visible=football;
 for(const a of people){if(a.kind==='runner'){const r=23.55+a.lane*1.1,c=104+2*Math.PI*r,v=point(time*(2.1+a.lane*.12)/c+a.offset,r);a.g.position.set(v[0],.15,v[1]);a.g.rotation.y=v[2];a.g.visible=runners;}else{const x=(a.i%2?1:-1)*(7+3*Math.sin(time*.25+a.i)),z=(Math.floor(a.i/2)-1.5)*15+Math.cos(time*.3+a.i)*2;a.g.position.set(x,.18,z);a.g.rotation.y=Math.atan2(bp.x-x,bp.z-z);a.g.visible=football;}a.limbs.forEach((l,j)=>l.rotation.x=Math.sin(time*(a.kind==='runner'?7:4)+a.i+(j%2)*Math.PI)*(j<2?.65:.5));}
 const slide=Math.floor(time/15)%2;if(slide!==boardSlide){boardSlide=slide;const ctx=board.material.map.image.getContext('2d');ctx.fillStyle='#294c43';ctx.fillRect(0,0,512,128);ctx.fillStyle='#eee9d8';ctx.font='600 50px Microsoft YaHei';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(slide?'社区运动 · 约250米':'青禾运动场  00 : 00',256,64,490);board.material.map.needsUpdate=true;}}
 function setQuality(v){if(!['high','medium','low'].includes(v))throw new Error('Unknown quality');level=v;root.traverse(o=>{if(o.userData.tier)o.visible=v==='high'||v==='medium'&&o.userData.tier<2;if(o.userData.grassDetail)o.count=v==='high'?22000:v==='medium'?10000:2000;});}
